def assign_existing_competition_series(apps, schema_editor):
    """Give every historical competition an isolated, deterministic series."""

    Competition = apps.get_model("leagues", "Competition")
    CompetitionSeries = apps.get_model("leagues", "CompetitionSeries")

    for competition in Competition.objects.iterator():
        # The primary-key-derived slug deliberately does not infer that two
        # similarly named historical competitions belong together.
        series = CompetitionSeries.objects.create(
            name=competition.name,
            slug=f"competition-{competition.pk}",
        )
        competition.series_id = series.pk
        competition.save(update_fields=["series"])


